{
  "explanation": "A Riemann sum approximates the area under a curve by adding up the areas of many thin rectangles. For y = x² from 0 to 2 we partition [0, 2] into n equal-width strips and take the height of each rectangle from a sample point (here the right endpoint). As n grows the stepped shape hugs the parabola more tightly and the total area approaches the exact integral ∫₀² x² dx = 8/3.",
  "manimCode": "const axes = new Axes({
  xRange: [0, 2.5, 0.5],
  yRange: [0, 5, 1],
  xLength: 9,
  yLength: 5.5,
  tips: true
});
axes.moveTo([0, -0.3, 0]);

const curve = axes.plot(x => x * x, { color: YELLOW, xRange: [0, 2] });
const xLabel = axes.getAxisLabels('x', 'y');

const title = new MathTex({ latex: '\\int_0^2 x^2\\,dx \\approx \\text{Riemann sum}' });
await title.waitForRender();
title.scale(0.7);
title.moveTo([0, 3.4, 0]);

scene.add(axes, curve, xLabel, title);

let n = 4;
let rects = [];
let sumLabel = null;

function rightRiemannSum(num) {
  const dx = 2 / num;
  let total = 0;
  for (let i = 1; i <= num; i++) {
    const x = i * dx;
    total += x * x * dx;
  }
  return total;
}

function buildRects(num) {
  for (const r of rects) scene.remove(r);
  rects = [];
  const dx = 2 / num;
  for (let i = 0; i < num; i++) {
    const left = i * dx;
    const right = (i + 1) * dx;
    const h = right * right; // right endpoint
    const verts = [
      axes.c2p(left, 0),
      axes.c2p(right, 0),
      axes.c2p(right, h),
      axes.c2p(left, h)
    ];
    const poly = new Polygon({ vertices: verts, color: BLUE_C });
    poly.setFill(BLUE_C, 0.45);
    poly.setStrokeWidth(1.5);
    rects.push(poly);
    scene.add(poly);
  }
  // keep curve on top
  scene.remove(curve);
  scene.add(curve);

  if (sumLabel) scene.remove(sumLabel);
  const approx = rightRiemannSum(num);
  const exact = 8 / 3;
  sumLabel = new Text({
    text: `n = ${num}   sum ≈ ${approx.toFixed(4)}   (exact = ${exact.toFixed(4)})`,
    color: WHITE,
    fontSize: 26
  });
  sumLabel.moveTo([0, -3.5, 0]);
  scene.add(sumLabel);
}

buildRects(n);

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({
  label: 'Rectangles (n)',
  min: 1,
  max: 60,
  value: n,
  step: 1,
  onChange: (val) => {
    n = Math.round(val);
    buildRects(n);
  }
});

controls.addButton({
  label: 'Reset n = 4',
  onClick: () => {
    n = 4;
    buildRects(n);
  }
});

await scene.wait(999999);"
}

